19	// formatMarker identifies the on-disk file format version.
20	const formatMarker = "edgefleet-heartbeats-v1"
21	
22	// onlineWindow is the maximum age of the latest telemetry for a node to be
23	// considered online. Exactly onlineWindow is still online.
24	const onlineWindow = 60 * time.Second
25	
26	// CorruptError means the on-disk data failed parsing or verification. The
27	// store refuses to read or write while corruption is present.
28	type CorruptError struct {
29		Path string
30		Err  error
31	}
32	
33	func (e *CorruptError) Error() string {
34		return fmt.Sprintf("data corruption detected in %s: %v", e.Path, e.Err)
35	}
36	
37	func (e *CorruptError) Unwrap() error { return e.Err }
38	
39	// IsCorrupt reports whether err is (or wraps) a CorruptError.
40	func IsCorrupt(err error) bool {
41		var ce *CorruptError
42		return errors.As(err, &ce)
43	}
44	
45	// nodeFile is the on-disk layout for one node.
46	type nodeFile struct {
47		Format   string      `json:"format"`
48		Checksum string      `json:"checksum"`
49		Records  []Heartbeat `json:"records"`
50	}
51	
52	// Store persists heartbeats as per-node JSON files under a data directory.
53	// Multiple Store instances (in the same or different processes) may safely
54	// access the same directory concurrently: a flock on the directory lock file
55	// serialises writers and lets queries take a shared lock, so a query never
56	// observes a partially written batch.
57	type Store struct {
58		dir      string
59		nodesDir string
60		lockPath string
61	}
62	
63	// OpenStore opens (and if needed creates) a data directory.
64	func OpenStore(dir string) (*Store, error) {
65		if err := os.MkdirAll(dir, 0o755); err != nil {
66			return nil, fmt.Errorf("cannot create data directory %s: %w", dir, err)
67		}
68		nodesDir := filepath.Join(dir, "nodes")
69		if err := os.MkdirAll(nodesDir, 0o755); err != nil {
70			return nil, fmt.Errorf("cannot create nodes directory %s: %w", nodesDir, err)
71		}
72		return &Store{dir: dir, nodesDir: nodesDir, lockPath: filepath.Join(dir, "lock")}, nil
73	}
74	
75	// Dir returns the data directory path.
76	func (s *Store) Dir() string { return s.dir }
77	
78	// nodePath maps a node id to its per-node file. Hex encoding keeps arbitrary
79	// node ids safe as filenames while remaining reversible.
80	func (s *Store) nodePath(nodeID string) string {
81		return filepath.Join(s.nodesDir, hex.EncodeToString([]byte(nodeID))+".json")
82	}
83	
84	// lock acquires the directory lock. Exclusive for writes, shared for reads.
85	// The returned closure releases the lock.
86	func (s *Store) lock(exclusive bool) (func(), error) {
87		f, err := os.OpenFile(s.lockPath, os.O_RDWR|os.O_CREATE, 0o600)
88		if err != nil {
89			return nil, fmt.Errorf("cannot open lock file %s: %w", s.lockPath, err)
90		}
91		how := syscall.LOCK_SH
92		if exclusive {
93			how = syscall.LOCK_EX
94		}
95		if err := syscall.Flock(int(f.Fd()), how); err != nil {
96			f.Close()
97			return nil, fmt.Errorf("cannot acquire data lock: %w", err)
98		}
99		return func() {
100			syscall.Flock(int(f.Fd()), syscall.LOCK_UN)
101			f.Close()
102		}, nil
103	}
104	
105	// checksumRecords returns a stable hash of the records. json.Marshal of a
106	// struct slice is deterministic for a given set of records.
107	func checksumRecords(records []Heartbeat) string {
108		data, _ := json.Marshal(records)
109		sum := sha256.Sum256(data)
110		return hex.EncodeToString(sum[:])
111	}
112	
113	// nodeIDFromPath recovers the node id a store file belongs to from its file
114	// name: nodePath writes each node's records to hex(nodeID)+".json", so the
115	// owner is exactly the string the base name decodes to. Node ids are compared
116	// as the exact strings they are — ids containing Chinese characters, spaces
117	// or slashes decode back unchanged and are never normalised or merged.
118	func nodeIDFromPath(path string) (string, error) {
119		base := filepath.Base(path)
120		if !strings.HasSuffix(base, ".json") {
121			return "", fmt.Errorf("file name %q is not a per-node heartbeat file", base)
122		}
123		raw, err := hex.DecodeString(strings.TrimSuffix(base, ".json"))
124		if err != nil {
125			return "", fmt.Errorf("file name %q does not encode a node id: %w", base, err)
126		}
127		return string(raw), nil
128	}
129	
130	// loadNodeFile reads and verifies the file for one node. A missing file means
131	// the node has no records (returns nil, nil). Any parse, checksum, ownership
132	// or structural failure is reported as a CorruptError.
133	//
134	// Ownership: the file belongs to exactly one node — the one encoded in its
135	// file name — and every record in it must declare that same node id. A file
136	// whose records name another node (for example another node's file copied
137	// over this one, format and checksum still intact) is not that node's
138	// telemetry: the whole file is refused as corrupt, no matter where the
139	// foreign record sits in the history and even if the latest record happens
140	// to name the right node.
141	//
142	// The file is decoded with the same strict rules as submit input: every
143	// telemetry field must be present, non-null and written once per record. A
144	// checksum that matches the zero-filled interpretation of a tampered record
145	// therefore cannot make a missing value look like real telemetry — the
146	// record is rejected before the checksum is consulted.
147	func loadNodeFile(path string) (*nodeFile, error) {
148		data, err := os.ReadFile(path)
149		if os.IsNotExist(err) {
150			return nil, nil
151		}
152		if err != nil {
153			return nil, &CorruptError{Path: path, Err: err}
154		}
155		nf, err := decodeStrictNodeFile(data)
156		if err != nil {
157			return nil, &CorruptError{Path: path, Err: err}
158		}
159		if nf.Format != formatMarker {
160			return nil, &CorruptError{Path: path, Err: fmt.Errorf("unknown format marker %q", nf.Format)}
161		}
162		if err := validateStoredRecords(nf.Records); err != nil {
163			return nil, &CorruptError{Path: path, Err: err}
164		}
165		if got := checksumRecords(nf.Records); got != nf.Checksum {
166			return nil, &CorruptError{Path: path, Err: fmt.Errorf("checksum mismatch: stored %s, computed %s", nf.Checksum, got)}
167		}
168		owner, err := nodeIDFromPath(path)
169		if err != nil {
170			return nil, &CorruptError{Path: path, Err: err}
171		}
172		for i, r := range nf.Records {
173			if r.NodeID != owner {
174				return nil, &CorruptError{Path: path, Err: fmt.Errorf(
175					"record %d: heartbeat declares node %q, but this file belongs to node %q",
176					i+1, r.NodeID, owner)}
177			}
178		}
179		return nf, nil
180	}
181	
182	// decodeStrictNodeFile parses the on-disk envelope without letting
183	// encoding/json defaults hide missing or duplicated data. The envelope has
184	// exactly three keys — format, checksum, records — each present, non-null and
185	// written once (a Unicode-escaped spelling of the same key still collides),
186	// and no other keys. Every element of records is decoded with
187	// decodeStrictHeartbeatObject, so a missing, null or duplicated telemetry
188	// field is an error naming the record and field rather than a zero value.
189	// Whitespace and key ordering carry no meaning and never cause a failure.
190	func decodeStrictNodeFile(data []byte) (*nodeFile, error) {
191		dec := json.NewDecoder(bytes.NewReader(data))
192		tok, err := dec.Token()
193		if err != nil {
194			return nil, fmt.Errorf("invalid JSON: %w", err)
195		}
196		if d, ok := tok.(json.Delim); !ok || d != '{' {
197			return nil, fmt.Errorf("invalid JSON: file must be a JSON object")
198		}
199	
200		var (
201			format   string
202			checksum string
203			records  []json.RawMessage
204	
205			seenFormat   bool
206			seenChecksum bool
207			seenRecords  bool
208		)
209		for dec.More() {
210			keyTok, err := dec.Token()
211			if err != nil {
212				return nil, fmt.Errorf("invalid JSON: %w", err)
213			}
214			key, ok := keyTok.(string)
215			if !ok {
216				return nil, fmt.Errorf("invalid JSON: envelope field name must be a string")
217			}
218			var val json.RawMessage
219			if err := dec.Decode(&val); err != nil {
220				return nil, fmt.Errorf("invalid value for envelope field %q: %w", key, err)
221			}
222			switch key {
223			case "format":
224				if seenFormat {
225					return nil, fmt.Errorf("duplicate envelope field %q", key)
226				}
227				seenFormat = true
228				if bytes.Equal(val, []byte("null")) {
229					return nil, fmt.Errorf("envelope field %q must not be null", key)
230				}
231				if err := json.Unmarshal(val, &format); err != nil {
232					return nil, fmt.Errorf("format must be a string: %w", err)
233				}
234			case "checksum":
235				if seenChecksum {
236					return nil, fmt.Errorf("duplicate envelope field %q", key)
237				}
238				seenChecksum = true
239				if bytes.Equal(val, []byte("null")) {
240					return nil, fmt.Errorf("envelope field %q must not be null", key)
241				}
242				if err := json.Unmarshal(val, &checksum); err != nil {
243					return nil, fmt.Errorf("checksum must be a string: %w", err)
244				}
245			case "records":
246				if seenRecords {
247					return nil, fmt.Errorf("duplicate envelope field %q", key)
248				}
249				seenRecords = true
250				if bytes.Equal(val, []byte("null")) {
251					return nil, fmt.Errorf("envelope field %q must not be null", key)
252				}
253				if err := json.Unmarshal(val, &records); err != nil {
254					return nil, fmt.Errorf("records must be an array of heartbeat objects: %w", err)
255				}
256			default:
257				return nil, fmt.Errorf("unknown envelope field %q", key)
258			}
259		}
260		// Consume the closing brace.
261		if _, err := dec.Token(); err != nil {
262			return nil, fmt.Errorf("invalid JSON: %w", err)
263		}
264		// Nothing may follow the single envelope object.
265		if _, err := dec.Token(); err != io.EOF {
266			if err == nil {
267				return nil, fmt.Errorf("invalid JSON: unexpected data after the envelope object")
268			}
269			return nil, fmt.Errorf("invalid JSON: %w", err)
270		}
271	
272		if !seenFormat {
273			return nil, fmt.Errorf("missing required envelope field %q", "format")
274		}
275		if !seenChecksum {
276			return nil, fmt.Errorf("missing required envelope field %q", "checksum")
277		}
278		if !seenRecords {
279			return nil, fmt.Errorf("missing required envelope field %q", "records")
280		}
281	
282		nf := &nodeFile{Format: format, Checksum: checksum, Records: make([]Heartbeat, 0, len(records))}
283		for i, raw := range records {
284			h, err := decodeStrictHeartbeatObject(raw)
285			if err != nil {
286				return nil, fmt.Errorf("record %d: %w", i+1, err)
287			}
288			nf.Records = append(nf.Records, h)
289		}
290		return nf, nil
291	}
292	
293	// validateStoredRecords checks the structural invariants of a strictly
294	// decoded record set: sorted by ascending seq with no duplicate seq and
295	// valid field values. Position numbers are 1-based to match decoder errors.
296	func validateStoredRecords(records []Heartbeat) error {
297		for i, r := range records {
298			if r.NodeID == "" {
299				return fmt.Errorf("record %d: field %q must not be empty", i+1, "node")
300			}
301			if r.Seq <= 0 {
302				return fmt.Errorf("record %d: field %q must be a positive integer, got %d", i+1, "seq", r.Seq)
303			}
304			if r.Version == "" {
305				return fmt.Errorf("record %d: field %q must not be empty", i+1, "version")
306			}
307			if r.Height < 0 {
308				return fmt.Errorf("record %d: field %q must be >= 0, got %d", i+1, "height", r.Height)
309			}
310			if r.Missed < 0 {
311				return fmt.Errorf("record %d: field %q must be >= 0, got %d", i+1, "missed", r.Missed)
312			}
313			if r.CollectedAt.IsZero() {
314				return fmt.Errorf("record %d: field %q is missing or invalid", i+1, "collected_at")
315			}
316			if i > 0 && records[i-1].Seq >= r.Seq {
317				return fmt.Errorf("records not sorted by ascending seq at record %d", i+1)
318			}
319		}
320		return nil
321	}
322	
323	// writeNodeFile persists records atomically: a temp file in the same
324	// directory is fsynced and renamed over the target, so a crash never leaves
325	// a half-written file.
326	func writeNodeFile(path string, records []Heartbeat) error {
327		if records == nil {
328			records = []Heartbeat{}
329		}
330		nf := nodeFile{
331			Format:   formatMarker,
332			Checksum: checksumRecords(records),
333			Records:  records,
334		}
335		data, err := json.MarshalIndent(nf, "", "  ")
336		if err != nil {
337			return err
338		}
339		return writeFileAtomic(path, data)
340	}
341	
342	func writeFileAtomic(path string, data []byte) error {
343		dir := filepath.Dir(path)
344		tmp, err := os.CreateTemp(dir, ".tmp-*")
345		if err != nil {
346			return err
347		}
348		tmpName := tmp.Name()
349		if _, err := tmp.Write(data); err != nil {
350			tmp.Close()
351			os.Remove(tmpName)
352			return err
353		}
354		if err := tmp.Sync(); err != nil {
355			tmp.Close()
356			os.Remove(tmpName)
357			return err
358		}
359		if err := tmp.Close(); err != nil {
360			os.Remove(tmpName)
361			return err
362		}
363		if err := os.Rename(tmpName, path); err != nil {
364			os.Remove(tmpName)
365			return err
366		}
367		// Best-effort fsync of the directory so the rename itself survives.
368		if d, err := os.Open(dir); err == nil {
369			d.Sync()
370			d.Close()
371		}
372		return nil
373	}
374	
375	// mergeRecord applies the single dedup/conflict rule shared by both submit
376	// phases (records within the batch, and the batch against stored history): a
377	// record's identity is its node id and seq together, and known must contain
378	// only records of that same node. If known already holds the identity, the
379	// incoming record is a duplicate when Heartbeat.Equal says the content is
380	// identical — collection time compared as an instant, node id and version
381	// compared as-is — and a conflict when any field differs. A conflict is an
382	// error naming the node and seq and changes nothing; a duplicate leaves
383	// known untouched and reports dup. Otherwise the record is appended and
384	// returned in the updated slice.
385	func mergeRecord(known []Heartbeat, r Heartbeat) (updated []Heartbeat, dup bool, err error) {
386		for _, e := range known {
387			if e.Seq == r.Seq {
388				if !e.Equal(r) {
389					return nil, false, fmt.Errorf("conflicting record for node %q seq %d: content differs", r.NodeID, r.Seq)
390				}
391				return known, true, nil
392			}
393		}
394		return append(known, r), false, nil
395	}
396	
397	// Submit persists a batch of heartbeats. The whole batch is validated and
398	// checked for duplicates/conflicts against stored data (and within the batch)
399	// before anything is written: a single invalid or conflicting record fails
400	// the batch with no changes. Duplicates are counted, not written. A
401	// successful return means the batch was durably persisted; a persistence
402	// failure is reported and previously queryable data is left intact.
403	func (s *Store) Submit(records []Heartbeat, receiveTime time.Time) (newCount, dupCount int, err error) {
404		if len(records) == 0 {
405			return 0, 0, fmt.Errorf("no heartbeat records provided")
406		}
407		for _, r := range records {
408			if err := ValidateHeartbeat(r, receiveTime); err != nil {
409				return 0, 0, fmt.Errorf("invalid heartbeat for node %q seq %d: %w", r.NodeID, r.Seq, err)
410			}
411		}
412	
413		unlock, err := s.lock(true)
414		if err != nil {
415			return 0, 0, err
416		}
417		defer unlock()
418	
419		// Deduplicate within the batch: same node+seq with equal content counts
420		// as a duplicate; same node+seq with differing content is a conflict.
421		merged := make(map[string][]Heartbeat)
422		for _, r := range records {
423			list, dup, err := mergeRecord(merged[r.NodeID], r)
424			if err != nil {
425				return 0, 0, err
426			}
427			if dup {
428				dupCount++
429				continue
430			}
431			merged[r.NodeID] = list
432		}
433	
434		// Merge with stored data per node, collecting new file contents.
435		type update struct {
436			path    string
437			records []Heartbeat
438		}
439		var updates []update
440		for nodeID, batch := range merged {
441			path := s.nodePath(nodeID)
442			nf, err := loadNodeFile(path)
443			if err != nil {
444				return 0, 0, err
445			}
446			existing := []Heartbeat{}
447			if nf != nil {
448				existing = nf.Records
449			}
450			for _, r := range batch {
451				var dup bool
452				existing, dup, err = mergeRecord(existing, r)
453				if err != nil {
454					return 0, 0, err
455				}
456				if dup {
457					dupCount++
458				} else {
459					newCount++
460				}
461			}
462			sort.Slice(existing, func(i, j int) bool { return existing[i].Seq < existing[j].Seq })
463			updates = append(updates, update{path: path, records: existing})
464		}
465	
466		// Persist. All updates are appends to previously verified data, so a
467		// failure here leaves every previously queryable record intact.
468		for _, u := range updates {
469			if err := writeNodeFile(u.path, u.records); err != nil {
470				return 0, 0, fmt.Errorf("failed to persist heartbeat batch: %w", err)
471			}
472		}
473		return newCount, dupCount, nil
474	}
475	
476	// HealthResult is the health judgement for one node based on real telemetry.
477	type HealthResult struct {
478		NodeID      string
479		Status      string // "online", "offline", "notelemetry"
480		Seq         int64
481		CollectedAt time.Time
482		Version     string
483		Height      int64
484		Missed      int64 // cumulative missed duties at the latest heartbeat
485		Findings    []string
486	
487		// Baseline-relative missed duties, populated only by HealthSince.
488		// BaselineSeq is the seq of the heartbeat the query was anchored to;
489		// BaselineMissed is the cumulative count at that heartbeat. When
490		// NewMissedKnown is false the cumulative counter went backwards
491		// somewhere between the baseline and the latest record, so the number of
492		// newly missed duties cannot be derived; Findings then reports the
493		// rollback. Missed always remains the latest cumulative count.
494		BaselineSeq    int64
495		BaselineMissed int64
496		NewMissed      int64
497		NewMissedKnown bool
498	}
499	
500	// rollbackFinding warns that the cumulative missed-duty counter decreased
501	// between two adjacent saved heartbeats (typically a node counter reset),
502	// which makes the endpoint difference unusable as the new-miss count.
503	const rollbackFinding = "累计漏签数回退"
504	
505	// Health judges a node from its latest telemetry (the record with the
506	// greatest seq). A node with no heartbeats returns Status "notelemetry". A
507	// query time earlier than the record's collection time is an error. Online
508	// status uses collection age against the query time: at most 60s is online
509	// (exactly 60s still online). Version skew and missed-duty rules follow the
510	// existing Evaluate rules.
511	func (s *Store) Health(nodeID string, at time.Time, expectedVersion string, toleratedMisses int) (HealthResult, error) {
512		return s.health(nodeID, at, expectedVersion, toleratedMisses, 0, false)
513	}
514	
515	// HealthSince judges a node the same way Health does, but the missed-duty
516	// alarm is measured against a user-supplied baseline heartbeat instead of the
517	// cumulative counter alone. baselineSeq must be the seq (> 0) of a record
518	// already saved for the node: the latest heartbeat stays the record with the
519	// greatest seq, and new missed duties are the latest cumulative count minus
520	// the count at the baseline record. Only a strict excess over
521	// toleratedMisses alarms; equality does not.
522	//
523	// The baseline affects this query only: stored history is never modified.
524	// Seqs between the baseline and the latest may have gaps. If the cumulative
525	// count decreases between any two adjacent saved records in that interval the
526	// new count is reported as unknown (NewMissedKnown == false) and a rollback
527	// finding is emitted, even if the latest count later climbs back past the
528	// baseline; decreases before the baseline are irrelevant. A node without
529	// telemetry, an unknown baseline seq, or a baseline newer than the latest
530	// record is an error — no other record is substituted and the baseline count
531	// is never assumed to be zero.
532	func (s *Store) HealthSince(nodeID string, at time.Time, expectedVersion string, toleratedMisses int, baselineSeq int64) (HealthResult, error) {
533		if baselineSeq <= 0 {
534			return HealthResult{}, fmt.Errorf("--missed-since-seq must be a positive integer, got %d", baselineSeq)
535		}
536		return s.health(nodeID, at, expectedVersion, toleratedMisses, baselineSeq, true)
537	}
538	
539	func (s *Store) health(nodeID string, at time.Time, expectedVersion string, toleratedMisses int, baselineSeq int64, useBaseline bool) (HealthResult, error) {
540		unlock, err := s.lock(false)
541		if err != nil {
542			return HealthResult{}, err
543		}
544		defer unlock()
545	
546		nf, err := loadNodeFile(s.nodePath(nodeID))
547		if err != nil {
548			return HealthResult{}, err
549		}
550		if nf == nil || len(nf.Records) == 0 {
551			if useBaseline {
552				return HealthResult{}, fmt.Errorf("node %q has no heartbeats; cannot use --missed-since-seq=%d as baseline", nodeID, baselineSeq)
553			}
554			return HealthResult{NodeID: nodeID, Status: "notelemetry", Findings: []string{"无遥测"}}, nil
555		}
556	
557		records := nf.Records // ascending seq, unique
558		latest := records[len(records)-1]
559	
560		if useBaseline {
561			if baselineSeq > latest.Seq {
562				return HealthResult{}, fmt.Errorf("--missed-since-seq=%d is newer than the latest heartbeat seq %d for node %q", baselineSeq, latest.Seq, nodeID)
563			}
564		}
565	
566		if at.Before(latest.CollectedAt) {
567			return HealthResult{}, fmt.Errorf("query time %s is earlier than collection time %s for node %q",
568				at.Format(time.RFC3339), latest.CollectedAt.Format(time.RFC3339), nodeID)
569		}
570	
571		age := at.Sub(latest.CollectedAt)
572		online := age <= onlineWindow
573	
574		findings := []string{}
575		if !online {
576			findings = append(findings, "offline")
577		}
578		if latest.Version != expectedVersion {
579			findings = append(findings, "version skew: "+latest.Version+" != "+expectedVersion)
580		}
581	
582		result := HealthResult{
583			NodeID:      nodeID,
584			Status:      "online",
585			Seq:         latest.Seq,
586			CollectedAt: latest.CollectedAt,
587			Version:     latest.Version,
588			Height:      latest.Height,
589			Missed:      latest.Missed,
590		}
591		if !online {
592			result.Status = "offline"
593		}
594	
595		if !useBaseline {
596			// Cumulative judgement: the current counter must strictly exceed the
597			// tolerance (mirrors Evaluate for callers that do not use a baseline).
598			node := Node{
599				ID:      nodeID,
600				Version: latest.Version,
601				Height:  latest.Height,
602				Missed:  int(latest.Missed),
603				Online:  online,
604			}
605			result.Findings = Evaluate(node, expectedVersion, toleratedMisses).Findings
606			return result, nil
607		}
608	
609		baselineIdx := -1
610		for i, r := range records {
611			if r.Seq == baselineSeq {
612				baselineIdx = i
613				break
614			}
615		}
616		if baselineIdx < 0 {
617			return HealthResult{}, fmt.Errorf("no saved heartbeat with seq %d for node %q; cannot use it as --missed-since-seq baseline", baselineSeq, nodeID)
618		}
619		baseline := records[baselineIdx]
620		result.BaselineSeq = baseline.Seq
621		result.BaselineMissed = baseline.Missed
622	
623		// Walk only saved records from the baseline up to the latest. Records are
624		// stored ascending by seq and seqs may legitimately have gaps, so any
625		// decrease between two adjacent saved records in this interval proves the
626		// cumulative counter reset somewhere in it; the endpoint difference alone
627		// must not be trusted even if the final count recovers.
628		rolledBack := false
629		for i := baselineIdx + 1; i < len(records); i++ {
630			if records[i].Missed < records[i-1].Missed {
631				rolledBack = true
632				break
633			}
634		}
635		if rolledBack {
636			result.NewMissedKnown = false
637			findings = append(findings, rollbackFinding)
638		} else {
639			result.NewMissedKnown = true
640			// No decrease was observed, so cumulative counts cannot have wrapped
641			// backwards within int64 range; the difference stays exact.
642			result.NewMissed = latest.Missed - baseline.Missed
643			if result.NewMissed > int64(toleratedMisses) {
644				findings = append(findings, "missed duties above tolerance")
645			}
646		}
647		result.Findings = findings
648		return result, nil
649	}
650	
651	// History returns all heartbeats for a node in ascending seq order, without
652	// duplicates. A node with no records returns an empty slice.
653	func (s *Store) History(nodeID string) ([]Heartbeat, error) {
654		unlock, err := s.lock(false)
655		if err != nil {
656			return nil, err
657		}
658		defer unlock()
659	
660		nf, err := loadNodeFile(s.nodePath(nodeID))
661		if err != nil {
662			return nil, err
663		}
664		if nf == nil {
665			return []Heartbeat{}, nil
666		}
667		return nf.Records, nil
668	}
