195	func cmdHealth(args []string) {
196		fs := newFlagSet("heartbeat health")
197		dataDir := fs.String("data-dir", defaultDataDir(), "data directory")
198		node := fs.String("node", "", "node id (required)")
199		atStr := fs.String("at", "", "query time (RFC3339); default: now")
200		expectedVersion := fs.String("expected-version", "", "expected version (required)")
201		toleratedMisses := fs.Int("tolerated-misses", -1, "tolerated missed duties, >= 0 (required)")
202		missedSinceSeq := fs.Int64("missed-since-seq", 0, "seq of a saved heartbeat to use as the missed-duty baseline; must be > 0 and exist for the node")
203		if err := fs.Parse(args); err != nil {
204			if err == flag.ErrHelp {
205				os.Exit(0)
206			}
207			os.Exit(2)
208		}
209		if *node == "" {
210			die("--node is required")
211		}
212		if *expectedVersion == "" {
213			die("--expected-version is required")
214		}
215		if *toleratedMisses < 0 {
216			die("--tolerated-misses is required and must be >= 0")
217		}
218		if isFlagPassed(fs, "missed-since-seq") && *missedSinceSeq <= 0 {
219			die("--missed-since-seq must be a positive integer")
220		}
221	
222		at := parseTimeFlag(*atStr, "--at")
223	
224		store, err := edgefleet.OpenStore(*dataDir)
225		if err != nil {
226			die("%v", err)
227		}
228	
229		var result edgefleet.HealthResult
230		if isFlagPassed(fs, "missed-since-seq") {
231			result, err = store.HealthSince(*node, at, *expectedVersion, *toleratedMisses, *missedSinceSeq)
232		} else {
233			result, err = store.Health(*node, at, *expectedVersion, *toleratedMisses)
234		}
235		if err != nil {
236			die("%v", err)
237		}
238	
239		if result.Status == "notelemetry" {
240			fmt.Printf("node=%s status=无遥测 findings=[无遥测]\n", result.NodeID)
241			return
242		}
243		fmt.Printf("node=%s status=%s seq=%d collected_at=%s version=%s height=%d missed=%d findings=%v\n",
244			result.NodeID, result.Status, result.Seq, result.CollectedAt.Format(time.RFC3339),
245			result.Version, result.Height, result.Missed, result.Findings)
246		if isFlagPassed(fs, "missed-since-seq") {
247			// missed above stays cumulative; this line states the alarm basis.
248			if result.NewMissedKnown {
249				fmt.Printf("baseline_seq=%d baseline_missed=%d new_missed=%d tolerated_misses=%d\n",
250					result.BaselineSeq, result.BaselineMissed, result.NewMissed, *toleratedMisses)
251			} else {
252				fmt.Printf("baseline_seq=%d baseline_missed=%d new_missed=无法判断 tolerated_misses=%d\n",
253					result.BaselineSeq, result.BaselineMissed, *toleratedMisses)
254			}
255		}
256	}
257	
258	// isFlagPassed reports whether the named flag was explicitly set on the
259	// command line, so an optional flag with a zero default can be distinguished
260	// from its absence.
261	func isFlagPassed(fs *flag.FlagSet, name string) bool {
262		passed := false
263		fs.Visit(func(f *flag.Flag) {
264			if f.Name == name {
265				passed = true
266			}
267		})
268		return passed
269	}
270	
271	func cmdHistory(args []string) {
272		fs := newFlagSet("heartbeat history")
273		dataDir := fs.String("data-dir", defaultDataDir(), "data directory")
274		node := fs.String("node", "", "node id (required)")
275		if err := fs.Parse(args); err != nil {
276			if err == flag.ErrHelp {
277				os.Exit(0)
278			}
279			os.Exit(2)
280		}
281		if *node == "" {
282			die("--node is required")
283		}
284	
285		store, err := edgefleet.OpenStore(*dataDir)
286		if err != nil {
287			die("%v", err)
288		}
289		records, err := store.History(*node)
290		if err != nil {
291			die("%v", err)
292		}
293		if len(records) == 0 {
294			fmt.Printf("node=%s no heartbeats\n", *node)
295			return
296		}
297		for _, r := range records {
298			fmt.Printf("node=%s seq=%d collected_at=%s version=%s height=%d missed=%d\n",
299				r.NodeID, r.Seq, r.CollectedAt.Format(time.RFC3339), r.Version, r.Height, r.Missed)
300		}
301	}
302	
303	func runDemo() {
304		nodes := []edgefleet.Node{
305			{ID: "val-eu-1", Region: "eu", Version: "1.26.0", Online: true},
306			{ID: "val-us-1", Region: "us", Version: "1.25.4", Online: true, Missed: 3},
307			{ID: "edge-ap-1", Region: "ap", Version: "1.26.0", Online: false},
308		}
309		unhealthy := 0
310		for _, node := range nodes {
311			health := edgefleet.Evaluate(node, "1.26.0", 1)
312			if !health.Healthy {
313				unhealthy++
314			}
315			fmt.Printf("node=%s healthy=%v findings=%v\n", health.Node, health.Healthy, health.Findings)
316		}
317		fmt.Println("rollout order:", edgefleet.Plan(nodes, "1.26.0"))
318		fmt.Printf("summary: %d of %d nodes need attention\n", unhealthy, len(nodes))
319	}
