619	func TestConcurrentSubmitConflict(t *testing.T) {
620		dir := t.TempDir()
621		receive := testBase
622		r1 := hb("n1", 1, receive.Add(-time.Minute), "1.0", 100, 0)
623		r2 := hb("n1", 1, receive.Add(-time.Minute), "2.0", 100, 0)
624	
625		var mu sync.Mutex
626		successes := 0
627		conflicts := 0
628		var errs []error
629		var wg sync.WaitGroup
630		for i := 0; i < 20; i++ {
631			wg.Add(1)
632			go func(i int) {
633				defer wg.Done()
634				store, err := OpenStore(dir)
635				if err != nil {
636					mu.Lock()
637					errs = append(errs, err)
638					mu.Unlock()
639					return
640				}
641				r := r1
642				if i%2 == 1 {
643					r = r2
644				}
645				_, _, err = store.Submit([]Heartbeat{r}, receive)
646				mu.Lock()
647				if err == nil {
648					successes++
649				} else if strings.Contains(err.Error(), "conflict") {
650					conflicts++
651				} else {
652					errs = append(errs, err)
