659			t.Fatalf("unexpected errors: %v", errs)
660		}
661		// All 10 submissions of the winning variant succeed (1 new + 9
662		// duplicates); all 10 of the losing variant hit the conflict.
663		if successes != 10 {
664			t.Errorf("successes=%d, want 10", successes)
665		}
